List rawList = new ArrayList();
rawList.add("tekst");
rawList.add(42); // KOMPILUJE SIE - ale to bomba zegarowa
for (Object element : rawList) {
    String text = (String) element; // wybuchnie na elemencie 42 -> ClassCastException
}

