List<String> lista = new ArrayList<>();
lista.add("Ala");
// lista.add(10); // BLAD KOMPILACJI - int nie mozna dodac do List<String>
// To DOBRZE, bo w oryginalnej, raw-type'owej wersji ten sam blad ujawnilby sie DOPIERO
// jako ClassCastException gdzies w runtime, przy proznym rzutowaniu elementu na String.

@SuppressWarnings("rawtypes")
static void wypiszWszystkie(List lista) {
    for (Object element : lista) {
        String text = (String) element;
        System.out.println(text);
    }
}

List raw = new ArrayList();
raw.add("Ala");
raw.add(99);
try {
    wypiszWszystkie(raw);
} catch (ClassCastException e) {
    System.out.println("Blad: " + e.getMessage() + " - generics zapobieglby temu juz przy DODAWANIU elementu 99");
}

