// To przypadek 'na lambde' - logika porownania jest KROTKA, BEZSTANOWA (nie potrzebuje
// zadnego wewnetrznego stanu miedzy wywolaniami) i uzywana JEDNORAZOWO w tym miejscu -
// osobna klasa dodalaby tylko niepotrzebny boilerplate.

class ThrottledAction implements Runnable {
    private final Runnable delegate;
    private final int every;
    private int count = 0;

    ThrottledAction(Runnable delegate, int every) { this.delegate = delegate; this.every = every; }

    public void run() {
        count++;
        if (count % every == 0) delegate.run();
    }
}

ThrottledAction throttled = new ThrottledAction(() -> System.out.println("Wykonano!"), 3);
for (int i = 0; i < 9; i++) throttled.run();
// Lambda by NIE wystarczyla, bo potrzebujemy WLASNEGO, MUTOWALNEGO pola 'count'
// przechowywanego MIEDZY kolejnymi wywolaniami run() - lambda nie ma miejsca na taki stan.

static int policzPolaPubliczne(Object obiekt) {
    int count = 0;
    for (var field : obiekt.getClass().getDeclaredFields()) {
        if (java.lang.reflect.Modifier.isPublic(field.getModifiers())) count++;
    }
    return count;
}

class A { public int x; public int y; private int z; }
class B { public String s; }
System.out.println(policzPolaPubliczne(new A())); // 2
System.out.println(policzPolaPubliczne(new B())); // 1

