// Mutowalna wersja:
class Punkt3DMutable {
    double x, y, z;
    Punkt3DMutable(double x, double y, double z) { this.x = x; this.y = y; this.z = z; }
}

// Niezmienna wersja:
record Punkt3D(double x, double y, double z) {
    Punkt3D przesun(double dx, double dy, double dz) {
        return new Punkt3D(x + dx, y + dy, z + dz);
    }
}

Punkt3DMutable m = new Punkt3DMutable(0, 0, 0);
Punkt3DMutable alias = m;
alias.x = 100; // 'przecieklo' do m!
System.out.println(m.x); // 100

Punkt3D p = new Punkt3D(0, 0, 0);
Punkt3D aliasP = p;
Punkt3D po = aliasP.przesun(100, 0, 0);
System.out.println(p.x() + " " + po.x()); // 0.0 100.0 - oryginal bez zmian

// var POPRAWIA czytelnosc:
// 1. var lista = new ArrayList<String>(); - typ w samej nazwie klasy po prawej.
// 2. var dzis = LocalDate.now(); - konstruktor/fabryka oczywista.
// 3. var i = 0; - klasyczny licznik petli.
// 4. var mapa = new HashMap<String, List<Integer>>(); - dlugi typ, skrocony bez utraty informacji.
// 5. var wynik = lista.stream().filter(x -> x > 0).toList(); - typ oczywisty z .toList().
//
// var POGARSZA czytelnosc:
// 1. var wynik = serwis.przetworz(dane); - typ zwracany metody nieznany bez zagladania do niej.
// 2. var x = policz(); - nazwa metody nic nie mowi o typie wyniku.
// 3. var dane = pobierzZBazy(id); - moze byc Optional/List/DTO, nie wiadomo bez sprawdzenia.
// 4. List<String> l = new ArrayList<>(); (var TU podkreslalby konkretny typ zamiast interfejsu List).
// 5. var wartosc = a ? metoda1() : metoda2(); - dwie rozne metody utrudniaja odgadniecie typu.

// 1. `List lista = new ArrayList();` -> RAW TYPE. Naprawa: List<KonkretnyTyp>.
// 2. `field.setAccessible(true); field.set(obj, val);` w kodzie biznesowym (nie w frameworku)
//    -> NADUZYCIE REFLEKSJI. Naprawa: zwykly setter/konstruktor.
// 3. `static List<String> WSPOLNA_LISTA = new ArrayList<>();` modyfikowana z wielu watkow
//    -> MUTOWALNY STAN WSPOLDZIELONY. Naprawa: niezmienna kolekcja/lokalny stan.
// 4. `void metoda(List<?> a, List<?> b)` gdy trzeba kopiowac elementy miedzy nimi
//    -> NADMIAR WILDCARDOW. Naprawa: PECS (List<? extends T> zrodlo, List<? super T> cel).
// 5. `switch (sealed) { case A -> ...; default -> "nieznany"; }` -> LYKAJACY DEFAULT.
//    Naprawa: usun default, obsluz WSZYSTKIE warianty jawnie.

class ProstyCache<K, V> {
    private final Map<K, V> dane = new HashMap<>();
    void put(K key, V value) { dane.put(key, value); }
    V get(K key) { return dane.get(key); }
}

ProstyCache<String, Integer> cache = new ProstyCache<>();
cache.put("wiek", 30);
Integer wiek = cache.get("wiek"); // ZERO rzutowan

