@SafeVarargs
static boolean waliduj(String haslo, java.util.function.Predicate<String>... reguly) {
    for (var regula : reguly) {
        if (!regula.test(haslo)) return false;
    }
    return true;
}

java.util.function.Predicate<String> minDlugosc = h -> h.length() >= 8;
java.util.function.Predicate<String> zawieraCyfre = h -> h.chars().anyMatch(Character::isDigit);

System.out.println(waliduj("krotkie", minDlugosc, zawieraCyfre));
System.out.println(waliduj("dlugieHaslo1", minDlugosc, zawieraCyfre));
System.out.println(waliduj("bezcyfry", minDlugosc, zawieraCyfre));

int n = 100_000;
Method method = Point.class.getMethod("hashCode");
long t1 = System.nanoTime();
for (int i = 0; i < n; i++) method.invoke(new Point(1, 2));
long reflectionTime = System.nanoTime() - t1;

MethodHandle handle = MethodHandles.lookup().findVirtual(Point.class, "hashCode", MethodType.methodType(int.class));
long t2 = System.nanoTime();
for (int i = 0; i < n; i++) handle.invoke(new Point(1, 2));
long handleTime = System.nanoTime() - t2;

System.out.println("Reflection: " + reflectionTime + " ns, MethodHandle: " + handleTime + " ns");
// Wniosek: MethodHandle zazwyczaj wygrywa po rozgrzaniu JIT-a, zgodnie z teoria lekcji.

