interface KsztaltVisitor<T> {
    T visitKolo(Kolo k);
    T visitProstokat(Prostokat p);
}
interface Ksztalt {
    <T> T accept(KsztaltVisitor<T> visitor);
}
class Kolo implements Ksztalt {
    double r;
    Kolo(double r) { this.r = r; }
    public <T> T accept(KsztaltVisitor<T> visitor) { return visitor.visitKolo(this); }
}
class Prostokat implements Ksztalt {
    double w, h;
    Prostokat(double w, double h) { this.w = w; this.h = h; }
    public <T> T accept(KsztaltVisitor<T> visitor) { return visitor.visitProstokat(this); }
}
// Visitor DAWAL exhaustiveness (kompilator wymusza implementacje WSZYSTKICH metod visit...)
// TEZ dla OTWARTYCH hierarchii - ale kosztem znacznie wiecej boilerplate'u niz sealed+switch,
