static void kopiuj(List<? extends Number> zrodlo, List<? super Number> cel) {
    for (Number n : zrodlo) cel.add(n);
}

List<Integer> zrodlo = List.of(1, 2, 3);
List<Number> cel = new ArrayList<>();
kopiuj(zrodlo, cel);
System.out.println(cel);

// PRZEWILDCARDOWANA wersja (NIE dziala):
// static void kopiujZle(List<?> zrodlo, List<?> cel) {
//     for (Object o : zrodlo) cel.add(o); // BLAD KOMPILACJI - nie da sie dodac do List<?>
// }
// List<?> to 'nieznany typ' - kompilator NIE POZWALA dodac do niej NICZEGO (poza null),
// bo nie wie, jaki typ faktycznie tam jest. PECS (producer extends, consumer super) daje
// precyzyjna kontrole: 'extends' pozwala CZYTAC jako Number, 'super' pozwala PISAC Number.

sealed interface Status permits Nowy, WTrakcie, Zakonczony /* , Anulowany */ {}
record Nowy() implements Status {}
record WTrakcie() implements Status {}
record Zakonczony() implements Status {}
// record Anulowany() implements Status {} // NOWY, 4. podtyp

static String opisz(Status s) {
    return switch (s) {
        case Nowy n -> "nowy";
        case WTrakcie w -> "w trakcie";
        case Zakonczony z -> "zakonczony";
        default -> throw new IllegalStateException("Nieznany status: " + s);
    };
}
// Program KOMPILUJE SIE mimo dodania 'Anulowany' do permits (default 'lapie' wszystko) -
// ale wywolanie opisz(new Anulowany()) wybuchnie IllegalStateException DOPIERO W RUNTIME.
// W przeciwienstwie do switcha BEZ default (Zadanie 14), gdzie ten sam blad zostalby
// wykryty JUZ przy kompilacji - default rzucajacy wyjatek jest 'mniejszym zlem' niz cichy
// default, ale nadal gorszy niz calkowity brak default dla exhaustywnego switcha.

// 1. Serializacja dowolnego obiektu do JSON (biblioteka ogolna) -> REFLEKSJA, bo trzeba
//    obslugiwac DOWOLNE, nieznane z gory typy klas uzytkownika.
// 2. Walidacja jednego pola formularza -> LAMBDA (Predicate<String>), bo to krotka,
//    bezstanowa logika uzyta raz.
// 3. System pluginow dla zewnetrznych dostawcow -> SPI/ServiceLoader + OTWARTY interfejs,
//    bo liczba dostawcow jest nieznana z gory i moze rosnac.
// 4. Reprezentacja wyniku operacji (Success/Failure, znany z gory zbior) -> SEALED+SWITCH,
//    bo chcemy exhaustiveness kompilatora.
// 5. Kod wywolywany MILION razy na sekunde, dynamiczne wywolanie metody -> METHODHANDLE,
//    bo wydajnosc jest krytyczna na tej 'goracej' sciezce.

