class PraktykiDoradca {
    static String zarekomenduj(String scenariusz) {
        if (scenariusz.contains("wtyczka") || scenariusz.contains("plugin")) return "polimorfizm/SPI";
        if (scenariusz.contains("znany z gory zbior")) return "sealed + switch";
        if (scenariusz.contains("krotkie") && scenariusz.contains("bezstanowe")) return "lambda";
        if (scenariusz.contains("wydajnosc") && scenariusz.contains("czesto")) return "MethodHandle";
        if (scenariusz.contains("framework")) return "refleksja";
        return "generics (domyslnie zamiast raw types)";
    }
}

String[] scenariusze = {"system wtyczek dla zewnetrznych dostawcow", "znany z gory zbior 3 statusow",
    "krotkie, bezstanowe porownanie", "kod wywolywany bardzo czesto, liczy sie wydajnosc",
    "framework skanujacy encje", "zwykla lista elementow"};
for (String s : scenariusze) System.out.println(s + " -> " + PraktykiDoradca.zarekomenduj(s));

int n = 500_000;
long t1 = System.nanoTime();
for (int i = 0; i < n; i++) new Point(1, 1).hashCode();
long direct = System.nanoTime() - t1;

Constructor<Point> ctor = Point.class.getDeclaredConstructor(int.class, int.class);
Method hashCodeMethod = Point.class.getMethod("hashCode");
long t2 = System.nanoTime();
for (int i = 0; i < n; i++) hashCodeMethod.invoke(ctor.newInstance(1, 1));
long reflection = System.nanoTime() - t2;

MethodHandle ctorHandle = MethodHandles.lookup().findConstructor(Point.class, MethodType.methodType(void.class, int.class, int.class));
MethodHandle hashHandle = MethodHandles.lookup().findVirtual(Point.class, "hashCode", MethodType.methodType(int.class));
long t3 = System.nanoTime();
for (int i = 0; i < n; i++) hashHandle.invoke((Point) ctorHandle.invoke(1, 1));
long handle = System.nanoTime() - t3;

System.out.println("=== RAPORT WYDAJNOSCI ===");
System.out.println("Bezposrednio: " + direct + " ns");
System.out.println("Refleksja:    " + reflection + " ns");
System.out.println("MethodHandle: " + handle + " ns");

// Wersja ZAMKNIETA (sealed):
sealed interface PowiadomienieZdarzenia permits UtworzonoKonto, UsunietoKonto {}
record UtworzonoKonto(String userId) implements PowiadomienieZdarzenia {}
record UsunietoKonto(String userId) implements PowiadomienieZdarzenia {}

// Wersja OTWARTA (polimorfizm):
interface KanalPowiadomien { void wyslij(String tresc); }
class EmailKanal implements KanalPowiadomien { public void wyslij(String t) { System.out.println("Email: " + t); } }
class SmsKanal implements KanalPowiadomien { public void wyslij(String t) { System.out.println("SMS: " + t); } }

// Sealed lepsze dla WEWNETRZNYCH typow zdarzen systemu (znasz z gory WSZYSTKIE typy
// zdarzen, chcesz gwarancje kompilatora przy dodaniu nowego). Polimorfizm lepszy dla
// KANALOW INTEGRACJI z zewnetrznymi systemami (nowy kanal - np. push notifications -
// moze zostac dodany przez inny zespol/plugin bez modyfikacji Twojego kodu). W realnym
// projekcie CZESTO oba podejscia wspolistnieja - sealed dla domeny wewnetrznej,
// polimorfizm dla punktow rozszerzalnosci.

record Config(int timeout, String host) {}

Config shared = new Config(30, "example.com");
Runnable task = () -> {
    for (int i = 0; i < 1000; i++) {
        Config lokalna = new Config(shared.timeout() + 1, shared.host()); // NOWY obiekt, nie mutacja
    }
    System.out.println(Thread.currentThread().getName() + " zakonczyl bez bledow");
};
Thread[] watki = new Thread[10];
for (int i = 0; i < 10; i++) { watki[i] = new Thread(task); watki[i].start(); }
for (Thread t : watki) { try { t.join(); } catch (InterruptedException e) {} }
System.out.println("Wszystkie watki zakonczone bez race condition");
// Dziala bez synchronizacji, bo KAZDY 'watek' tworzy WLASNE, NOWE obiekty Config zamiast
// mutowac wspoldzielony 'shared' - nie ma zadnej sytuacji jednoczesnego zapisu do tego
// samego stanu, bo zapisu (mutacji) w ogole NIE MA.

@java.lang.annotation.Retention(java.lang.annotation.RetentionPolicy.RUNTIME)
@java.lang.annotation.Target(java.lang.annotation.ElementType.FIELD)
@interface Wymagane {}

class Formularz {
    @Wymagane String imie;
    @Wymagane String email;
    String telefon;
}

static List<String> waliduj(Object obiekt) throws IllegalAccessException {
    List<String> bledy = new ArrayList<>();
    for (var field : obiekt.getClass().getDeclaredFields()) {
        if (field.isAnnotationPresent(Wymagane.class)) {
            field.setAccessible(true);
            if (field.get(obiekt) == null) bledy.add("Pole '" + field.getName() + "' jest wymagane");
        }
    }
    return bledy;
}

Formularz f = new Formularz();
f.imie = "Ala";
System.out.println(waliduj(f)); // [Pole 'email' jest wymagane]

// STARE API (2005):
// interface Repository { List findAll(); void save(Object item); Map getIndex(); List findByIds(List ids); }
//
// NOWE, generyczne API:
interface Repository<T, ID> {
    List<T> findAll();
    void save(T item);
    Map<ID, T> getIndex();
    List<T> findByIds(List<ID> ids);
}
// Dodanie SAMYCH parametrow typu (List -> List<T>) do ISTNIEJACYCH metod jest BINARNIE
// KOMPATYBILNE dzieki type erasure - skompilowany bajtkod DALEJ ma sygnature 'List findAll()',
// tylko z dodatkowymi metadanymi generycznymi widocznymi dla kompilatora. NIE byloby binarnie
// kompatybilne: zmiana liczby parametrow metody, zmiana nazwy klasy/interfejsu, usuniecie
// metody - te zmiany wymagalyby rekompilacji istniejacych klientow API.

sealed interface Ksztalt permits A, B, C, D /* , E */ {}
record A() implements Ksztalt {} record B() implements Ksztalt {}
record C() implements Ksztalt {} record D() implements Ksztalt {}
// record E() implements Ksztalt {} // 5. podtyp

static String nazwa(Ksztalt k) { return switch (k) { case A a -> "A"; case B b -> "B"; case C c -> "C"; case D d -> "D"; }; }
static int bokow(Ksztalt k) { return switch (k) { case A a -> 0; case B b -> 4; case C c -> 3; case D d -> 6; }; }
static boolean jestOkragly(Ksztalt k) { return switch (k) { case A a -> true; case B b -> false; case C c -> false; case D d -> false; }; }
// Po dodaniu E do permits, WSZYSTKIE TRZY metody (nazwa, bokow, jestOkragly) przestaja sie
// kompilowac NIEZALEZNIE od siebie - kompilator wskazuje DOKLADNIE te trzy miejsca w kodzie,
// gdzie brakuje obslugi nowego przypadku - to jest cala 'siatka bezpieczenstwa' refaktoryzacji.

// CHECKLIST CODE REVIEW - rozdzial _14_advancedjava:
// 1. Czy uzyto raw types (List, Map bez <>)? Jesli tak - poprawic na generyki.
// 2. Czy lambda ma wlasny stan (pole)? Jesli tak - zamienic na klasy.
// 3. Czy refleksja jest uzywana w kodzie biznesowym (nie frameworku)? Jesli tak - zapytac czemu.
// 4. Czy sealed switch ma 'lykajacy' default? Sprawdzic czy exhaustiveness nie zostala oslabiona.
// 5. Czy nowa klasa domenowa MOGLABY byc niemutowalna (record)? Jesli tak - preferowac to.
// 6. Czy pola typu List/Map/tablica sa defensywnie kopiowane w konstruktorze/getterze?
// 7. Czy uzycie var utrudnia czytelnosc (typ nieoczywisty z prawej strony)?
// 8. Czy hierarchia typow powinna byc sealed (zamknieta, znana z gory) czy interfejs
//    (otwarta, rozszerzalna) - czy wybor jest swiadomy?

// OSOBISTE PODSUMOWANIE rozdzialu _14_advancedjava:
// Rozdzial obejmowal 5 klastrow: generics (1-7), programowanie funkcyjne (8-11),
// adnotacje/refleksja (12-18), nowoczesny system typow (19-22), oraz niezmiennosc/var/SPI
// (23-28). Klaster generykow byl fundamentem, na ktorym opieraly sie prawie wszystkie
// pozostale tematy (kolekcje, Stream API). Klaster funkcyjny (lambdy, method reference)
// jest prawdopodobnie NAJCZESCIEJ uzywany w codziennym kodzie - lambdy pojawiaja sie
// praktycznie wszedzie. Klaster refleksji/adnotacji byl NAJTRUDNIEJSZY konceptualnie,
